    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public {
        uint balBefore = recipient.balance;

        bool revertedFirst;
        c.getFirstWithdrawalBonus(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedFirst = true;
        } else {
            revertedFirst = false;
        }

        uint balAfterFirst = recipient.balance;

        bool revertedSecond;
        c.getFirstWithdrawalBonus(recipient); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            revertedSecond = true;
        } else {
            revertedSecond = false;
        }

        assert(
            revertedFirst ||
            (
                balAfterFirst == balBefore + 100 &&
                revertedSecond &&
                recipient.balance == balAfterFirst
            )
        );
    }

    receive() external payable {}
}

