// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrancy_bonus c;

    function setUp() public {
        c = new Reentrancy_bonus();
    }

    function _run(address recipient) internal {
        uint balBefore = recipient.balance;
        bool revertedFirst;
        try c.getFirstWithdrawalBonus(recipient) {
            revertedFirst = false;
        } catch {
            revertedFirst = true;
        }
        uint balAfterFirst = recipient.balance;
        bool revertedSecond;
        try c.getFirstWithdrawalBonus(recipient) {
            revertedSecond = false;
        } catch {
            revertedSecond = true;
        }
        assertTrue(revertedFirst ||
            (
                balAfterFirst == balBefore + 100 &&
                revertedSecond &&
                recipient.balance == balAfterFirst
            ));
    }

    function testFuzz_run(address recipient) public {
        vm.assume(recipient.code.length == 0 && uint160(recipient) > 0xffff && recipient != address(this) && recipient != address(c) && recipient != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && recipient != 0x000000000000000000636F6e736F6c652e6c6f67 && recipient != 0x4e59b44847b379578588920cA78FbF26c0B4956C && recipient != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(recipient);
    }

    receive() external payable {}
}
